import{_ as o,l as i,o as e,c as n,v as t,p as m,x as l,d as h,i as s,S as d}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"批大小与 roofline 拐点","description":"","frontmatter":{"title":"批大小与 roofline 拐点","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/batch-roofline-knee.md","filePath":"llm/batch-roofline-knee.md","lastUpdated":1789023840000}'),p={name:"llm/batch-roofline-knee.md"};function c(B,a,T,_,f,E){const r=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="批大小与-roofline-拐点" tabindex="-1">批大小与 roofline 拐点 <a class="header-anchor" href="#批大小与-roofline-拐点" aria-label="Permalink to &quot;批大小与 roofline 拐点&quot;">​</a></h1><div class="epigraph"><p>同一份权重被更多序列复用时，强度随 batch 上升；越过屋顶比之后，再加大 batch 主要加吞吐、不再降逐步延迟。</p><footer>—— 屋顶线见 Williams et al., CACM 2009；连续批使 batch 成为时间上的变量见 Yu et al., Orca, OSDI 2022</footer></div><p><a href="/llm/arithmetic-intensity-decode">上一课</a>定义了 decode 的 \\(I\\)。本课把 \\(I\\) 看成 \\(B\\) 的函数，找出拐点：从带宽绑定进入算力绑定的那个并发。连续批让 \\(B\\) 随时间变，产品感觉是「人一多，每个字变慢」还是「人一多，总吞吐上去」——取决于你在拐点哪一侧。<a href="/llm/continuous-batching">连续批处理</a>改成员；本课只写工作点，不重写调度器。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>小 \\(B\\) 时每步时间 \\(\\approx (W+\\mathrm{KV})/\\mathrm{bandwidth}\\)，与 \\(B\\) 几乎无关，TPOT 稳定、吞吐线性于 \\(B\\)。\\(B\\) 大到 GEMM 打满 Tensor Core，逐步时间改由 \\(\\mathrm{FLOPs}(B)/\\mathrm{peak}\\) 决定，随 \\(B\\) 上升，TPOT 变差，吞吐接近常数（算力屋顶）。缺口是估计拐点 \\(B^\\star\\)，否则 SLA 会写成互相矛盾的「高并发且低 TPOT」。</p><p>KV 随 \\(B\\) 涨，容量墙可能先于拐点到来：还没打满算力就 OOM。此时优化应减 KV 字节，而不是再加卡的 FLOPS。反之，KV 很瘦（MLA、短上下文）时，拐点来得早，再堆并发只伤延迟。</p><p><span class="marginnote">拐点不是一个通用整数。它随模型宽、量化、是否投机（\\(n_q\\gt 1\\)）、以及 prefill 是否混入而变。同一集群白天聊天与夜间批推理，工作点可以分居两侧。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>令 \\(T_{\\mathrm{mem}}=(W_{\\mathrm{bytes}}+B\\cdot \\overline{\\mathrm{KV}})/(\\eta_b B_{\\mathrm{HBM}})\\)，\\(T_{\\mathrm{cmp}}=\\mathrm{FLOPs}(B)/(\\eta_c\\,\\mathrm{peak})\\)。\\(B^\\star\\) 满足 \\(T_{\\mathrm{mem}}\\approx T_{\\mathrm{cmp}}\\)。权重主导时 \\(B^\\star\\) 大致与 \\(W/\\overline{\\mathrm{KV}}\\) 和屋顶比有关：KV 越大，\\(B^\\star\\) 越小（每条序列自己就带来很多字节）。测：\\(B=1,2,4,\\ldots\\) 画 TPOT 与 tokens/s。TPOT 平坦段是带宽区；开始爬升是过拐点。吞吐的弯折应对上。</p><p>混合批次：<a href="/llm/chunked-prefill">chunked prefill</a> 把算力密的工作掺进 decode 拍，等效 \\(I\\) 上升，拐点左移，正在流式的用户 TPOT 抖动。分离 prefill/decode 池是为了让 decode 池停在选定的 \\(B\\) 一侧。</p>',10)),(e(),m(d,null,{default:l(()=>[s(r,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20B1%5B%22%E5%B0%8F%20batch%22%5D%20--%3E%20MEM%5B%22TPOT%20%E5%B9%B3%E5%9D%A6%2C%20%E5%90%9E%E5%90%90%E9%9A%8F%20B%20%E5%8D%87%22%5D%0A%20%20B2%5B%22%E8%BF%87%E6%8B%90%E7%82%B9%22%5D%20--%3E%20CMP%5B%22TPOT%20%E7%88%AC%E5%8D%87%2C%20%E5%90%9E%E5%90%90%E5%B0%81%E9%A1%B6%22%5D%0A%20%20KV%5B%22KV%20%E5%85%88%E6%BB%A1%22%5D%20--%3E%20CAP%5B%22%E5%AE%B9%E9%87%8F%E5%A2%99%E6%97%A9%E4%BA%8E%E6%8B%90%E7%82%B9%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>权重在 batch 维复用，KV 不在请求之间复用（前缀共享除外）。因此拐点同时被两股力量拉：量化权重 → \\(W\\) 小 → 更容易被 KV 主导、拐点可能更早；量化 KV → 每条更瘦 → 可以更大 \\(B\\) 才碰到容量，拐点右移。投机加宽 \\(n_q\\)，等效把部分「batch 复用」换成「查询复用」，单请求也能略微右移工作点。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>不要把训练的「最优 global batch」当成服务 \\(B^\\star\\)。不要为了吞吐把 decode 池推过拐点还不改 SLA。尾延迟由最高 \\(B\\) 与最长 \\(n\\) 的乘积决定，平均值好看不够。后课把时间换成焦耳。</p><p>出处：Williams et al., 2009；Yu et al., OSDI 2022。Pope et al. 2022 讨论推理并行度与阶段。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>\\(B^\\star\\) 是 \\(T_{\\mathrm{mem}}\\approx T_{\\mathrm{cmp}}\\) 的并发；左侧加 \\(B\\) 加吞吐，右侧加 \\(B\\) 加 TPOT。</li><li>容量墙可早于拐点；先减 KV 再堆并发。</li><li>混合 prefill 使拐点移动并造成 TPOT 抖动。</li><li>权重量化与 KV 量化对拐点的方向相反。</li><li>测量用 TPOT–\\(B\\) 曲线，不要只用 GPU 利用率。</li><li>下一课：逐步时间换成每 token 能耗。</li><li>出处：Williams et al., 2009；Yu et al., 2022。</li></ul>',7))])}const u=o(p,[["render",c]]);export{b as __pageData,u as default};
